<script setup>
import {ref,computed} from 'vue';import {readLibrary,writeLibrary} from '../services/travelLibrary';import {language} from '../i18n';import UnifiedTripMap from '../components/UnifiedTripMap.vue';import ActivityImage from '../components/ActivityImage.vue';
const props=defineProps({kind:String});const emit=defineEmits(['open','add','back']);const records=ref([]),error=ref(''),filter=ref('route'),detail=ref(null);try{records.value=readLibrary(props.kind);}catch(e){error.value=e.message;}
const visible=computed(()=>props.kind==='history'?records.value:records.value.filter(r=>r.type===filter.value));
function remove(id){try{const next=records.value.filter(r=>r.id!==id);writeLibrary(props.kind,next);records.value=next;}catch(e){error.value=e.message;}}
function clear(){if(!confirm(language.value==='zh'?'确认清空本机全部历史记录？收藏不会删除。':'Clear all local history? Favorites will remain.'))return;try{writeLibrary('history',[]);records.value=[];}catch(e){error.value=e.message;}}
</script><template><main class="travel-library"><button class="text-button" @click="$emit('back')">← {{language==='zh'?'返回旅程':'Back to journey'}}</button><h1>{{kind==='history'?(language==='zh'?'历史记录':'Travel history'):(language==='zh'?'收藏夹':'Saved journeys')}}</h1><p>{{language==='zh'?'仅保存在当前浏览器，不跨设备同步。历史是当时的快照，天气、交通和开放时间需要重新确认。':'Stored in this browser only, without device sync. Snapshots may contain outdated weather, travel and opening information.'}}</p><p v-if="error" role="alert">{{error}}</p><nav v-if="kind==='favorites'"><button v-for="(label,type) in (language==='zh'?{route:'旅行路线',attraction:'景点',restaurant:'餐厅',hotel:'酒店'}:{route:'Routes',attraction:'Places',restaurant:'Restaurants',hotel:'Hotels'})" :key="type" class="outline" @click="filter=type" :aria-pressed="filter===type">{{label}}</button></nav><button v-else class="text-button" @click="clear">{{language==='zh'?'清空历史':'Clear history'}}</button><p v-if="!visible.length">{{language==='zh'?'暂无记录':'No saved records'}}</p><article v-for="r in visible" :key="r.id"><h2>{{r.snapshot?.destination.displayName||r.name}}</h2><p>{{r.snapshot?.settings.date}} · {{r.snapshot?.settings.days}} {{r.snapshot?(language==='zh'?'天':'days'):r.city}} · {{new Date(r.createdAt).toLocaleString()}}</p><template v-if="r.snapshot"><button class="outline" @click="emit('open',r.snapshot,false)">{{language==='zh'?'查看原始行程':'View original snapshot'}}</button><button class="outline" @click="emit('open',r.snapshot,true)">{{language==='zh'?'复制并继续编辑':'Copy and edit'}}</button></template><template v-else><ActivityImage v-if="r.data.image||r.data.photo" :place="r.data"/><button class="outline" @click="detail=r">{{language==='zh'?'详情与地图':'Details and map'}}</button><button class="outline" @click="emit('add',r)">{{language==='zh'?'加入旅行计划':'Add to a trip'}}</button></template><button class="text-button" @click="remove(r.id)">{{language==='zh'?'删除 / 取消收藏':'Remove'}}</button></article><section v-if="detail"><h2>{{detail.name}}</h2><p>{{detail.data.address}} · {{detail.data.latitude}}, {{detail.data.longitude}}</p><UnifiedTripMap v-if="detail.data.destination" :destination="detail.data.destination" :places="[detail.data]" :active="detail.data.id"/></section></main></template>
<style scoped>.travel-library{max-width:1100px;margin:auto;padding:50px 5%;color:#203c34;background:#faf8f3;min-height:75vh}.travel-library h1,.travel-library h2{font-family:'Source Han Serif SC',serif}.travel-library article{padding:24px 0;border-bottom:1px solid #deddd2}.travel-library button{margin:6px;min-height:40px}.travel-library p{line-height:1.7}.travel-library .outline{color:#203c34;border-color:#d8ddd1}.travel-library .outline[aria-pressed=true]{background:#e4ebde}.travel-library :deep(.activity-image){min-height:116px}</style>
